#!/usr/bin/env node
// Regenerates the self-hosted Manrope and Poppins font modules (GL#123) so no Worker page loads
// fonts from Google. Each target gets a TypeScript module holding its woff2 subsets as base64
// (the repo's existing pattern for binary assets, see member-portal/src/assets/favicon.ts), plus
// the fonts' SIL OFL licence files beside it.
//
//   node scripts/build-font-modules.mjs
//
// Needs npm and network access: it runs `npm pack` for the pinned Fontsource packages below into
// a temporary directory. Bump a version here, re-run, and commit the regenerated files.

import { execFileSync } from 'node:child_process';
import { copyFileSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const PACKAGES = {
  Manrope: { name: '@fontsource/manrope', version: '5.3.0' },
  Poppins: { name: '@fontsource/poppins', version: '5.3.0' },
};

// Only the weights each page uses, and the subsets its languages need. The browser downloads a
// subset only when the page has a character in its unicode-range.
export const TARGETS = [
  {
    // Portal locales include Vietnamese (Manrope's vietnamese subset; Poppins covers it in
    // latin-ext) and Hindi (Poppins devanagari). CJK locales fall back to the system stack.
    out: 'member-portal/src/assets/fontData.ts',
    faces: {
      Manrope: { weights: [500, 700], subsets: ['latin', 'latin-ext', 'vietnamese'] },
      Poppins: { weights: [400, 600, 700], subsets: ['latin', 'latin-ext', 'devanagari'] },
    },
  },
  {
    // The widget is English-only: event titles in Manrope 500, everything else in Poppins.
    out: 'svbc-calendars/src/fontData.ts',
    faces: {
      Manrope: { weights: [500], subsets: ['latin', 'latin-ext'] },
      Poppins: { weights: [400, 600, 700], subsets: ['latin', 'latin-ext'] },
    },
  },
];

/**
 * @param {{ source: string, faces: Array<{ family: string, weight: number, subset: string, unicodeRange: string, base64: string }> }} input
 * @returns {string} the TypeScript module text
 */
export function renderFontModule({ source, faces }) {
  const entries = faces
    .map(
      (f) =>
        `  {\n    family: '${f.family}',\n    weight: ${f.weight},\n    subset: '${f.subset}',\n` +
        `    unicodeRange: '${f.unicodeRange}',\n    woff2Base64:\n      '${f.base64}',\n  },`
    )
    .join('\n');
  return `// Generated by scripts/build-font-modules.mjs from ${source}. Do not edit; re-run the script.
// SIL Open Font License 1.1: see the OFL-*.txt files beside this module.

export interface EmbeddedFont {
  family: 'Manrope' | 'Poppins';
  weight: number;
  subset: string;
  unicodeRange: string;
  woff2Base64: string;
}

export const EMBEDDED_FONTS: readonly EmbeddedFont[] = [
${entries}
];
`;
}

function main() {
  const root = join(dirname(fileURLToPath(import.meta.url)), '..');
  const work = mkdtempSync(join(tmpdir(), 'svbc-fonts-'));
  try {
    const dirs = {};
    for (const [family, pkg] of Object.entries(PACKAGES)) {
      const tgz = execFileSync('npm', ['pack', `${pkg.name}@${pkg.version}`, '--silent'], { cwd: work, encoding: 'utf8' }).trim();
      const dir = join(work, family);
      execFileSync('mkdir', ['-p', dir]);
      execFileSync('tar', ['-xzf', join(work, tgz), '-C', dir]);
      dirs[family] = join(dir, 'package');
    }
    const source = Object.values(PACKAGES)
      .map((p) => `${p.name}@${p.version}`)
      .join(' and ');

    for (const target of TARGETS) {
      const faces = [];
      for (const [family, { weights, subsets }] of Object.entries(target.faces)) {
        const ranges = JSON.parse(readFileSync(join(dirs[family], 'unicode.json'), 'utf8'));
        for (const weight of weights) {
          for (const subset of subsets) {
            const file = join(dirs[family], 'files', `${family.toLowerCase()}-${subset}-${weight}-normal.woff2`);
            if (!ranges[subset]) throw new Error(`${family} has no ${subset} subset`);
            faces.push({ family, weight, subset, unicodeRange: ranges[subset], base64: readFileSync(file).toString('base64') });
          }
        }
      }
      const out = join(root, target.out);
      writeFileSync(out, renderFontModule({ source, faces }));
      for (const family of Object.keys(target.faces)) {
        copyFileSync(join(dirs[family], 'LICENSE'), join(dirname(out), `OFL-${family}.txt`));
      }
      console.log(`wrote ${target.out} (${faces.length} faces)`);
    }
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
